// Ask all four containers what they are running.
//
// Four independently tagged images: on 2026-08-10 the four UAT images spanned
// 18h41m of build times. Checking only the API would call a deploy live while
// a portal serves days-old code — and most changes in this repo are front-end.
//
// Service names, not host.docker.internal: the deploy stack publishes no host
// ports (founder 2026-07-20), and n8n sits on the same compose network, so
// this is the same path cloudflared uses.
const targets = [
  { name: 'api',           url: 'http://api-uat:4000/api/version' },
  { name: 'consumer',      url: 'http://consumer-uat:3008/api/version' },
  { name: 'authenticator', url: 'http://authenticator-uat:3001/api/version' },
  { name: 'admin',         url: 'http://admin-uat:3003/api/version' },
];

const results = [];
for (const t of targets) {
  try {
    const r = await this.helpers.httpRequest({ url: t.url, timeout: 5000, json: true });
    results.push({ ...t, commit: r.commit, builtAt: r.builtAt });
  } catch (e) {
    // A 404 is not "down" — /api/version shipped on 2026-08-10, so an image
    // without it predates that commit. Saying so beats a generic outage alarm.
    const msg = String(e.message || e);
    results.push({ ...t, error: msg.includes('404') ? 'stale-image (no /api/version)' : msg });
  }
}

const down = results.filter((r) => r.error && !r.error.startsWith('stale-image'));
const stale = results.filter((r) => r.error && r.error.startsWith('stale-image'));
const unstamped = results.filter((r) => !r.error && (r.commit === 'unknown' || r.commit === 'dev'));

// Four containers should be running one commit. A split means a partial
// deploy — the failure this whole check exists for.
const commits = [...new Set(results.filter((r) => r.commit).map((r) => r.commit))];
const split = down.length === 0 && stale.length === 0 && commits.length > 1;

const lines = [];
if (down.length) lines.push(`⚠️ 連唔到：${down.map((r) => r.name).join(', ')}`);
if (stale.length) lines.push(`⚠️ Image 舊過 2026-08-10（deploy 未生效）：${stale.map((r) => r.name).join(', ')}`);
if (unstamped.length) lines.push(`⚠️ 未蓋章 build（唔經 ci/ci-run.sh）：${unstamped.map((r) => `${r.name}=${r.commit}`).join(', ')}`);
if (split) lines.push(`⚠️ 四個容器行緊唔同 commit：${results.map((r) => `${r.name}=${String(r.commit).slice(0, 8)}`).join(', ')}`);

// Healthy: stay silent. An alert that fires when nothing is wrong is how
// people learn to ignore alerts.
return [{ json: { alert: lines.length > 0, text: `Certifine UAT\n${lines.join('\n')}`, results } }];
